      "https://static-api-statements.tnet.ge/uploads/202603/20260317/statements/EFpmrbS69b97385672ac.webp",
      "https://static-api-statements.tnet.ge/uploads/202603/20260317/statements/zpQsg1h69b97386667ed.webp",
      "https://static-api-statements.tnet.ge/uploads/202603/20260317/statements/BrK7DCV69b97385dc84f.webp",
